// Precedence: () and [] bind tighter than *

// 1. Array of Pointers
int* arr_ptr[10];      // Array[10] of (int*)

// 2. Pointer to Array
int (*ptr_arr)[10];    // Pointer to (Array[10] of int)

// 3. Function Pointer Definition
typedef int (*BinaryOp)(int, int);

// 4. Array of Function Pointers
BinaryOp op_table[5];  // Array[5] of BinaryOp

// 5. Complex Function Pointer Declaration
// Pointer to a function (float) returning (int*)
int* (*ComplexFP)(float);

// 6. Function returns a pointer to an array
int (*(*FuncReturnsPtrToArr)())[10];
// Right-Left parsing rule is crucial for these types.
